class color32
{
public:
    unsigned char c[4];
    color32() {}
    color32(unsigned char r, unsigned char g, unsigned char b, unsigned char a)
    {
        c[0] = r;
        c[1] = g;
        c[2] = b;
        c[3] = a;
    }
};

class TextString
{
public:
    char padding[0x48];
    color32 color;
    virtual void Draw();
};

class FlashText : public TextString
{
public:
    bool flash;
    char padding[3];
    color32 color1;
    color32 color2;
    float flash_time;
    float flash_alpha;

    void Draw();
};

void FlashText::Draw()
{
    if (flash)
    {
        color = color32(
            color1.c[0] + (color2.c[0] - color1.c[0]) * (flash_alpha + 0.5f),
            color1.c[1] + (color2.c[1] - color1.c[1]) * (flash_alpha + 0.5f),
            color1.c[2] + (color2.c[2] - color1.c[2]) * (flash_alpha + 0.5f),
            color2.c[3]);
    }
    TextString::Draw();
}
